using System;using System.Web;using System.Web.Services;using WebPortal.Assets.Classes;
namespace WebPortal.Assets{public partial class TransferApproval:System.Web.UI.Page{static AssetBAL S=>new AssetBAL();static long U=>Convert.ToInt64(HttpContext.Current.User.Identity.Name.ToString());protected void Page_Load(object sender,EventArgs e){}[WebMethod]public static object List(){var rows=S.List("Transfer",null,null,"Requested");rows.Merge(S.List("Transfer",null,null,"Pending"));return AssetBAL.Rows(rows);}[WebMethod]public static ApiResult Action(long id,string action,string remarks){try{var status=S.TransferStatus(id,U);if(!string.Equals(status,"Requested",StringComparison.OrdinalIgnoreCase)&&!string.Equals(status,"Pending",StringComparison.OrdinalIgnoreCase))return ApiResult.Fail("Only requested transfers can be approved or rejected.");var approve=string.Equals(action,"Approve",StringComparison.OrdinalIgnoreCase)||string.Equals(action,"Approved",StringComparison.OrdinalIgnoreCase);S.Action("Transfer",id,approve?"Approve":"Reject",remarks,U);S.NormalizeTransferDecision(id,approve?"Approved":"Rejected",U);return ApiResult.Ok(null,approve?"Transfer approved successfully.":"Transfer rejected.");}catch(Exception ex){return ApiResult.Fail(ex.Message);}}}}
